// Rango de busqueda: los ultimos 30 dias, para que cubra el CSV que deja el
// datafono (no solo el dia anterior).
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());
const desde = new Date(hoy + 'T00:00:00Z');
desde.setUTCDate(desde.getUTCDate() - 30);

return [{ json: { hoy, desde: desde.toISOString().slice(0, 10) } }];

// Prepara las ventas del datafono, quitando las que ya estan.
//
// La clave de cada cobro es fecha|hora|importe|ultimos4 de la tarjeta: con eso no se
// importa dos veces el mismo cobro, aunque el flujo se ejecute varias veces.
//
// Ademas se descartan los cobros que ya estan en la tienda (mismo dia, mismo importe
// y mismo concepto), por si el CSV se ha volcado de nuevo.
const entrada = $input.first().json ?? {};

const digitos = (s) => String(s ?? '').replace(/[^0-9]/g, '');
const aNumero = (bruto) => {
  if (bruto === null || bruto === undefined) return null;
  if (typeof bruto === 'number') return Number.isFinite(bruto) ? bruto : null;
  let s = String(bruto).trim().replace(/[^0-9.,]/g, '');
  if (!s) return null;
  const coma = s.lastIndexOf(',');
  const punto = s.lastIndexOf('.');
  if (coma >= 0 && punto >= 0) {
    s = coma > punto ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (coma >= 0) {
    s = s.replace(',', '.');
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const filas = $('Parsear el CSV').all().map((i) => i.json ?? {});

const staticData = $getWorkflowStaticData('global');
staticData.cobros = Array.isArray(staticData.cobros) ? staticData.cobros : [];
const yaImportados = new Set(staticData.cobros.map(String));

const enTienda = $('Ventas que ya tiene la tienda').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((v) => v && v.id !== undefined)
  .map((v) => [String(v.fecha ?? ''), Number(v.importe ?? 0).toFixed(2), String(v.concepto ?? '').trim().toLowerCase()].join('|'));

const ventas = [];
const omitidas = [];

for (const fila of filas) {
  const fecha = String(fila.fecha ?? '').trim();
  const hora = String(fila.hora ?? '').trim();
  const importe = aNumero(fila.importe);
  const tarjeta = digitos(fila.tarjeta);
  const concepto = String(fila.concepto ?? '').trim() || 'Cobro con tarjeta';

  if (!fecha || importe === null || importe <= 0) {
    omitidas.push({ fecha, hora, importe: fila.importe, motivo: 'fila ilegible' });
    continue;
  }

  const clave = [fecha, hora, importe.toFixed(2), tarjeta.slice(-4)].join('|');
  if (yaImportados.has(clave)) {
    omitidas.push({ fecha, hora, importe, motivo: 'ya importado' });
    continue;
  }
  if (enTienda.includes([fecha, importe.toFixed(2), concepto.toLowerCase()].join('|'))) {
    omitidas.push({ fecha, hora, importe, motivo: 'ya esta en la tienda' });
    continue;
  }

  yaImportados.add(clave);
  ventas.push({ clave, fecha, importe, concepto, forma_pago: 'tarjeta' });
}

// Un item por venta: el nodo HTTP hace una peticion por item.
return ventas.map((v) => ({ json: { ...entrada, ...v, omitidas, total: ventas.length } }));

// Guarda los cobros importados y resume lo que ha pasado.
//
// La clave de cada cobro (fecha|hora|importe|ultimos4) queda en los datos estaticos
// del flujo: si se ejecuta otra vez, esos cobros no se vuelven a registrar.
const venta = $input.first().json ?? {};
const preparacion = $('Preparar las ventas').first().json ?? {};

const staticData = $getWorkflowStaticData('global');
staticData.cobros = Array.isArray(staticData.cobros) ? staticData.cobros : [];

const errores = [];
const registradas = [];

// El nodo HTTP devuelve un item por venta, en el mismo orden que las preparadas:
// se usan los indices para saber que clave de cobro corresponde a cada una.
const entradas = $input.all();
entradas.forEach((item, indice) => {
  const v = item.json ?? {};
  const origen = (preparacion.ventas ?? [])[indice];
  if (v.id !== undefined && v.concepto !== undefined) {
    registradas.push(v);
    if (origen?.clave) staticData.cobros.push(origen.clave);
  } else {
    errores.push(v);
  }
});

// Solo se guardan los ultimos 2000 cobros: el historico no crece sin limite.
staticData.cobros = Array.from(new Set(staticData.cobros)).slice(-2000);

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const total = registradas.reduce((s, v) => s + Number(v.importe ?? 0), 0);

const cuerpo = [
  'Importacion del datáfono:',
  '',
  'Cobros importados: ' + registradas.length,
  'Cobros omitidos (ya estaban): ' + ((preparacion.omitidas ?? []).length),
  'Total importado: ' + euros(total),
].concat(errores.length ? ['', 'Errores: ' + errores.length] : []).join('\n');

return [{ json: { ...venta, registradas, errores, omitidas: preparacion.omitidas ?? [], total: Number(total.toFixed(2)), cuerpo } }];
